package com.yinfires.icecore.oven;
import com.mojang.blaze3d.vertex.PoseStack; import net.minecraft.client.Minecraft; import net.minecraft.client.renderer.MultiBufferSource; import net.minecraft.client.renderer.blockentity.BlockEntityRenderer; import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider; import net.minecraft.client.renderer.entity.ItemRenderer; import net.minecraft.world.item.ItemDisplayContext;
public final class OvenRenderer implements BlockEntityRenderer<OvenBlockEntity> { public OvenRenderer(BlockEntityRendererProvider.Context c){} @Override public void render(OvenBlockEntity oven,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){ItemRenderer r=Minecraft.getInstance().getItemRenderer();pose.pushPose();var state=oven.getBlockState();float yaw=switch(state.getValue(ModOven.FACING)){case SOUTH->180F;case WEST->90F;case EAST->270F;default->0F;};pose.translate(.5,.0,.5);pose.mulPose(com.mojang.math.Axis.YP.rotationDegrees(yaw));pose.translate(-.5,0,-.5);for(int i=0;i<OvenBlockEntity.CAPACITY;i++){var s=oven.getItem(i);if(s.isEmpty())continue;pose.pushPose();pose.translate(.5F,.145F+i*.035F,.5F);pose.mulPose(com.mojang.math.Axis.XP.rotationDegrees(90F));pose.scale(.43F,.43F,.43F);r.renderStatic(s,ItemDisplayContext.FIXED,light,overlay,pose,buffers,oven.getLevel(),i);pose.popPose();}pose.popPose();}}
